# Google Document AI OCR and layout extraction
from google.cloud import documentai_v1 as documentai

def extract_layout_and_text(uri: str) -> dict:
    """
    Extracts OCR text and layout information (blocks, lines, tables, etc.)
    from a Document AI-processed document given its GCS URI.

    Returns a dict with:
        - "text": plain string of all detected text
        - "layout": list of dicts, each representing a layout element
                     with type, content, and bounding polygon.
    """
    client = documentai.DocumentProcessorServiceClient()
    name = f"projects/{client._gaia_project_id}/locations/us-central1/processors/automl-ocr"
    document = {"gcs_source": {"uri": uri}}
    request = {"document": document, "name": name}

    response = client.process_document(request=request)

    document = response.document
    plain_text = ""
    layout_elements = []

    # Collect plain text
    for token in document.tokens:
        plain_text += token.text + " "

    # Collect layout elements (blocks, paragraphs, tables, form fields, etc.)
    for entity in document.entities:
        element = {
            "type": entity.type_.name,
            "content": entity.text_anchor.content or "",
            "confidence": entity.confidence,
            "polygon": [],
        }
        for layout in document.layout:
            if layout.provenance[0].index == entity.text_anchor.start_token:
                for point in layout.bounding_poly.normalized_vertices:
                    element["polygon"].append(
                        (point.x, point.y)
                    )  # normalized coordinates (0-1 range)

        layout_elements.append(element)

    return {"text": plain_text.strip(), "layout": layout_elements}
